insert into public.chem_legal_releases (id,label,checked_on,entry_count,is_current,coverage,gaps) values ('th-chemical-2026-10-09-v1','ชุดตรวจทาน 9 ตุลาคม 2569','2026-10-09',2089,true,'{"hazard":"ครบการเปลี่ยนแปลง 21 รายการของฉบับที่ 8 พร้อมรายการตรวจยืนยันอื่นเฉพาะส่วน ยังไม่ครบทุกบัญชี","reporting":"นำเข้า 206 รายการ; ยืนยันการจับคู่ CAS เฉพาะส่วน","labour":"นำเข้า 1,516 ลำดับจากบัญชี; แยกรายการรอตรวจทานและ CAS ขัดแย้ง","health":"เกณฑ์งาน/กลุ่มสาร และการจับคู่ชื่อสารเฉพาะส่วน ยังไม่ครบ 72 รายการย่อย","exposure":"นำเข้า 324 ลำดับหลัก; รายการย่อยและค่าที่รอตรวจทานยังห้ามใช้ยืนยัน"}'::jsonb,'["ยังไม่ได้ตรวจรับรายการและเงื่อนไขครบทุกแถว การไม่พบไม่ใช่ข้อยกเว้นกฎหมาย","ประกาศแก้คำผิด 7 ตุลาคม 2557 ยังไม่ได้รับต้นฉบับ","ข้อมูลสกัดจาก PDF อาจมีอักขระหรือ CAS ไม่สมบูรณ์ รายการเหล่านี้อยู่ในคิวตรวจทาน","สารผสมต้องตรวจองค์ประกอบจาก SDS ทีละสาร รวมถึงความเข้มข้นและการใช้งาน"]'::jsonb);
