insert into public.chem_legal_entries (id,release_id,category,name,aliases,cas_numbers,source_cas,agency,list_ref,revision,source_id,source_page,hazardous_type,conditions,review_state,legal_status,effective_from,effective_to,details) values ('hazard-group-5.6','th-chemical-2026-10-09-v1','hazard','บัญชี 5.6 คุณสมบัติอันตราย 10 กลุ่ม / วอ./อก.32',array[]::text[],array[]::text[],'','กรมโรงงานอุตสาหกรรม','บัญชี 5.6 / วอ./อก.32','ฉบับที่ 2 พ.ศ.2558 / ประกาศ พ.ศ.2565','thirtytwo',1,null,'กรณีผลิตหรือนำเข้าสารที่มีคุณสมบัติตามบัญชี 5.6 และไม่มีหน่วยงานอื่นรับผิดชอบ ให้ตรวจหน้าที่ วอ./อก.32 แยกต่างหาก โดยพิจารณาปริมาณสารเดี่ยวมากกว่า 1 เมตริกตันต่อปีและเงื่อนไขการแจ้ง','verified','active',null,null,'{"group":true,"note":"การไม่พบชื่อในฐาน CAS ไม่ได้แปลว่าไม่อยู่ภายใต้บัญชี 5.6 และไม่ใช้เกณฑ์ 100 กก. ของ วอ./อก.7 แทน","related_sources":["hz"]}'::jsonb);
insert into public.chem_legal_entries (id,release_id,category,name,aliases,cas_numbers,source_cas,agency,list_ref,revision,source_id,source_page,hazardous_type,conditions,review_state,legal_status,effective_from,effective_to,details) values ('hazard-1.2-9-v8','th-chemical-2026-10-09-v1','hazard','สารสำคัญ จุลชีพ สารสกัดจากพืช หรือผลิตภัณฑ์ เพื่อควบคุมการเจริญเติบโตของพืช รวมการกระตุ้น ยับยั้ง ชะลอการเจริญเติบโต การออกดอก ติดผล เปลี่ยนสี หรือออกราก',array[]::text[],array[]::text[],'','กรมวิชาการเกษตร','บัญชี 1.2 ลำดับ 9','ฉบับที่ 8 พ.ศ.2568','no8',4,2,'ยกเว้นชิ้นส่วนจากพืชที่มีลักษณะธรรมชาติ ด้วยวิธีการแปรรูปผลิตภัณฑ์ เช่น ตากแห้ง สับ บดให้เป็นผง หมักด้วยน้ำโดยไม่เติมสารอื่น','verified','active','2025-07-08',null,'{"note":"บัญชีกลุ่มสาร ไม่จำกัด CAS; ต้องพิจารณาวัตถุประสงค์และวิธีแปรรูป"}'::jsonb);
insert into public.chem_legal_entries (id,release_id,category,name,aliases,cas_numbers,source_cas,agency,list_ref,revision,source_id,source_page,hazardous_type,conditions,review_state,legal_status,effective_from,effective_to,details) values ('hazard-1.2-10-v8','th-chemical-2026-10-09-v1','hazard','สารสำคัญ จุลชีพ สารสกัดจากพืช หรือผลิตภัณฑ์ เพื่อป้องกัน กำจัด ทำลาย ไล่ ล่อ ควบคุมแมลงหรือสัตว์ที่เป็นศัตรูพืช',array[]::text[],array[]::text[],'','กรมวิชาการเกษตร','บัญชี 1.2 ลำดับ 10','ฉบับที่ 8 พ.ศ.2568','no8',4,2,'ยกเว้นชิ้นส่วนจากพืชที่มีลักษณะธรรมชาติ ด้วยวิธีการแปรรูปผลิตภัณฑ์ เช่น ตากแห้ง สับ บดให้เป็นผง หมักด้วยน้ำโดยไม่เติมสารอื่น','verified','active','2025-07-08',null,'{"note":"บัญชีกลุ่มสาร ไม่จำกัด CAS; ต้องพิจารณาวัตถุประสงค์และวิธีแปรรูป"}'::jsonb);
insert into public.chem_legal_entries (id,release_id,category,name,aliases,cas_numbers,source_cas,agency,list_ref,revision,source_id,source_page,hazardous_type,conditions,review_state,legal_status,effective_from,effective_to,details) values ('hazard-1.2-11-v8','th-chemical-2026-10-09-v1','hazard','สารสำคัญ จุลชีพ สารสกัดจากพืช หรือผลิตภัณฑ์ เพื่อป้องกัน กำจัด ทำลาย ควบคุมโรคพืช',array[]::text[],array[]::text[],'','กรมวิชาการเกษตร','บัญชี 1.2 ลำดับ 11','ฉบับที่ 8 พ.ศ.2568','no8',4,2,'ยกเว้นชิ้นส่วนจากพืชที่มีลักษณะธรรมชาติ ด้วยวิธีการแปรรูปผลิตภัณฑ์ เช่น ตากแห้ง สับ บดให้เป็นผง หมักด้วยน้ำโดยไม่เติมสารอื่น','verified','active','2025-07-08',null,'{"note":"บัญชีกลุ่มสาร ไม่จำกัด CAS; ต้องพิจารณาวัตถุประสงค์และวิธีแปรรูป"}'::jsonb);
insert into public.chem_legal_entries (id,release_id,category,name,aliases,cas_numbers,source_cas,agency,list_ref,revision,source_id,source_page,hazardous_type,conditions,review_state,legal_status,effective_from,effective_to,details) values ('hazard-1.2-12-v8','th-chemical-2026-10-09-v1','hazard','สารสำคัญ จุลชีพ สารสกัดจากพืช หรือผลิตภัณฑ์ เพื่อป้องกัน กำจัด ทำลาย ควบคุมวัชพืชหรือพืชที่ไม่พึงประสงค์',array[]::text[],array[]::text[],'','กรมวิชาการเกษตร','บัญชี 1.2 ลำดับ 12','ฉบับที่ 8 พ.ศ.2568','no8',4,2,'ยกเว้นชิ้นส่วนจากพืชที่มีลักษณะธรรมชาติ ด้วยวิธีการแปรรูปผลิตภัณฑ์ เช่น ตากแห้ง สับ บดให้เป็นผง หมักด้วยน้ำโดยไม่เติมสารอื่น','verified','active','2025-07-08',null,'{"note":"บัญชีกลุ่มสาร ไม่จำกัด CAS; ต้องพิจารณาวัตถุประสงค์และวิธีแปรรูป"}'::jsonb);
insert into public.chem_legal_entries (id,release_id,category,name,aliases,cas_numbers,source_cas,agency,list_ref,revision,source_id,source_page,hazardous_type,conditions,review_state,legal_status,effective_from,effective_to,details) values ('hazard-4.2-22-v8','th-chemical-2026-10-09-v1','hazard','คลอรีนและสารที่ให้คลอรีน / chlorine and chlorine releasing substances',array[]::text[],array[]::text[],'','สำนักงานคณะกรรมการอาหารและยา','บัญชี 4.2 ลำดับ 22','ฉบับที่ 8 พ.ศ.2568','no8',6,3,'ในผลิตภัณฑ์ที่ใช้ในบ้านเรือนหรือทางสาธารณสุข เพื่อการซักผ้าขาว ฆ่าเชื้อโรค ทำความสะอาดพื้น ฝาผนัง เครื่องสุขภัณฑ์ วัสดุอื่น ๆ หรือแก้ไขการอุดตันของท่อหรือทางระบายสิ่งปฏิกูล','verified','active','2025-07-08',null,'{"note":"บัญชีกลุ่มสาร ไม่ผูก CAS คลอรีนตัวเดียวแทนสารทั้งกลุ่ม"}'::jsonb);
insert into public.chem_legal_entries (id,release_id,category,name,aliases,cas_numbers,source_cas,agency,list_ref,revision,source_id,source_page,hazardous_type,conditions,review_state,legal_status,effective_from,effective_to,details) values ('hazard-1.2-8-repeal8','th-chemical-2026-10-09-v1','hazard','สารสกัดจากพืช เช่น สะเดา ข่า ตะไคร้หอม ฯลฯ เพื่อประโยชน์ ในการป้องกันกําจัดแมลงศัตรูพืช',array[]::text[],array[]::text[],'-','กรมวิชาการเกษตร','บัญชี 1.2 ลำดับ 8','ยกเลิกโดยฉบับที่ 8 พ.ศ.2568','no8',1,2,'สารสกัดจากพืชเพื่อประโยชน์ในการป้องกันกำจัดแมลงศัตรูพืช','verified','repealed',null,'2025-07-08','{"note":"ยกเลิกเฉพาะรายการเดิม ไม่ใช่ข้อยกเว้นจากบัญชีกลุ่มหรือกฎหมายอื่น","related_sources":["hz"]}'::jsonb);
insert into public.chem_legal_entries (id,release_id,category,name,aliases,cas_numbers,source_cas,agency,list_ref,revision,source_id,source_page,hazardous_type,conditions,review_state,legal_status,effective_from,effective_to,details) values ('hazard-4.1-99-repeal8','th-chemical-2026-10-09-v1','hazard','น้ํามันตะไคร้หอม หรือ ซิโตรเนลลาออยล์ (citronella oil)',array[]::text[],array['8000-29-1']::text[],'8000-29-1','สำนักงานคณะกรรมการอาหารและยา','บัญชี 4.1 ลำดับ 99','ยกเลิกโดยฉบับที่ 8 พ.ศ.2568','no8',1,1,'ในผลิตภัณฑ์ที่ใช้ในบ้านเรือนหรือทางสาธารณสุขที่นํามาใช้เพื่อ
