-- Versioned reference data; accessed through authenticated server routes only.
create table public.chem_legal_releases (
  id text primary key,
  label text not null,
  checked_on date not null,
  entry_count integer not null check (entry_count > 0),
  is_current boolean not null default false,
  coverage jsonb not null check (jsonb_typeof(coverage) = 'object'),
  gaps jsonb not null check (jsonb_typeof(gaps) = 'array'),
  created_at timestamptz not null default now()
);
create unique index chem_legal_one_current on public.chem_legal_releases(is_current) where is_current;

create table public.chem_legal_sources (
  release_id text not null references public.chem_legal_releases(id),
  id text not null,
  title text not null,
  url text not null check (url like 'https://%'),
  note text not null default '',
  checked_on date not null,
  primary key(release_id, id)
);

create table public.chem_legal_entries (
  release_id text not null references public.chem_legal_releases(id),
  id text not null,
  category text not null check (category in ('hazard','reporting','labour','health','exposure')),
  name text not null,
  aliases text[] not null default '{}',
  cas_numbers text[] not null default '{}',
  source_cas text not null default '',
  agency text not null,
  list_ref text not null,
  revision text not null,
  source_id text not null,
  source_page integer not null check (source_page > 0),
  hazardous_type integer check (hazardous_type between 1 and 4),
  conditions text not null,
  review_state text not null check (review_state in ('verified','pending','conflict')),
  legal_status text not null check (legal_status in ('active','repealed','superseded')),
  effective_from date,
  effective_to date,
  details jsonb not null default '{}' check (jsonb_typeof(details) = 'object'),
  primary key(release_id, id),
  foreign key(release_id, source_id) references public.chem_legal_sources(release_id, id),
  check (effective_to is null or effective_from is null or effective_to > effective_from)
);
create index chem_legal_entries_cas on public.chem_legal_entries using gin(cas_numbers);

create unique index chem_substances_company_identity on public.chem_substances(company_id, id);
create table public.chem_legal_assessments (
  id uuid primary key default gen_random_uuid(),
  company_id text not null references public.company_settings(company_id),
  substance_id uuid,
  cas text not null check (cas ~ '^[0-9]{2,7}-[0-9]{2}-[0-9]$'),
  release_id text not null references public.chem_legal_releases(id),
  review_status text not null check (review_status in ('pending','reviewed')),
  review_note text not null check (length(review_note) <= 3000),
  actor_id text not null,
  actor_name text not null,
  snapshot jsonb not null check (jsonb_typeof(snapshot) = 'object'),
  created_at timestamptz not null default now(),
  foreign key(company_id, substance_id) references public.chem_substances(company_id, id),
  check (review_status <> 'reviewed' or length(trim(review_note)) >= 10)
);
create index chem_legal_assessments_company on public.chem_legal_assessments(company_id, created_at desc);
create index chem_legal_assessments_substance on public.chem_legal_assessments(company_id, substance_id, created_at desc);

alter table public.chem_legal_releases enable row level security;
alter table public.chem_legal_sources enable row level security;
alter table public.chem_legal_entries enable row level security;
alter table public.chem_legal_assessments enable row level security;
revoke all on public.chem_legal_releases, public.chem_legal_sources, public.chem_legal_entries, public.chem_legal_assessments from anon, authenticated;
-- Reference releases and snapshots are immutable to application credentials.
revoke all on public.chem_legal_releases, public.chem_legal_sources, public.chem_legal_entries, public.chem_legal_assessments from service_role;
grant select on public.chem_legal_releases, public.chem_legal_sources, public.chem_legal_entries, public.chem_legal_assessments to service_role;
grant insert on public.chem_legal_assessments to service_role;

